sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // 1. Date of Birth cannot be in the future
    if (!current.date_of_birth.nil()) {
        var today = new GlideDate();
        var dob = new GlideDate();
        dob.setValue(current.date_of_birth);

        if (dob.compareTo(today) > 0) {
            current.setAbortAction(true);
            gs.addErrorMessage('Date of Birth cannot be in the future.');
            return;
        }
    }

    // 2. Changing email clears Email verified until OTP sets it again
    if (current.operation() == 'update' && current.email.changes()) {
        current.email_verified = false;
        gs.addInfoMessage('Email address was changed. Email verification has been reset to unverified until re-verified via OTP.');
    }

})(current, previous);
